<script lang="ts">
	import { goto } from '$app/navigation';
	import { base } from '$app/paths';
	import type { Community, CommunityJoinRequest } from '$lib/api';
	let { data } = $props();
	const community = data.community as Community;
	let name = $state(community.name);
	let mode = $state<'open' | 'approval'>(community.mode === 'approval' ? 'approval' : 'open');
	let draws = $state(community.draws);
	let message = $state(''); let saving = $state(false); let copied = $state(false);
	let tab = $state<'general' | 'members' | 'join' | 'integrations'>('general');
	let members = $state<CommunityJoinRequest[]>([]); let discord = $state(''); let webhook = $state('');
	async function saveGeneral() { saving=true; message=''; try { const {api}=await import('$lib/api'); await api.updateCommunity(community.id,{name:name.trim(),mode,draws}); message='Community settings saved.';} catch(e){message=(e as Error).message;} finally{saving=false;} }
	async function saveIntegration() { saving=true; message=''; try { const {api}=await import('$lib/api'); await api.updateIntegration(community.id,{discord,webhook}); message='Integration settings saved.';} catch(e){message=(e as Error).message;} finally{saving=false;} }
	async function loadMembers(){try{const {api}=await import('$lib/api'); members=await api.communityMembers(community.id);}catch(e){message=(e as Error).message}}
	async function loadIntegration(){try{const {api}=await import('$lib/api'); const i=await api.integration(community.id); discord=i.discord; webhook=i.webhook;}catch(e){message=(e as Error).message}}
	function selectTab(next:typeof tab){tab=next;message='';if(next==='members')loadMembers();if(next==='integrations')loadIntegration()}
	async function copyCode(){await navigator.clipboard?.writeText(community.code);copied=true}
	let shared = $state(false);
	async function shareInvite(){
		const url = `${window.location.origin}${base}/communities?code=${encodeURIComponent(community.code)}`;
		const text = `Join ${community.name} on Open-Skill — use code ${community.code}`;
		if (navigator.share) { try { await navigator.share({ title: community.name, text, url }); } catch { /* user cancelled */ } return; }
		try { await navigator.clipboard.writeText(url); shared = true; setTimeout(() => (shared = false), 2000); } catch { /* clipboard unavailable */ }
	}
</script>
<svelte:head><title>{community.name} settings — Open-Skill</title></svelte:head>
<div class="page-wrap"><div class="page-inner"><div class="nav"><button class="btn btn-ghost" onclick={()=>goto(`${base}/leaderboard?communityId=${encodeURIComponent(community.id)}`)}>← Leaderboard</button></div><section class="card hero"><div><p class="label-caps">Community settings</p><h1>{community.name}</h1><p>{community.members} members · Invite code <strong>{community.code}</strong></p></div><div style="display:flex; gap:10px; flex-wrap:wrap;"><button class="btn btn-secondary" onclick={copyCode}>{copied?'Copied':'Copy invite code'}</button><button class="btn btn-primary" onclick={shareInvite}>{shared?'Shared!':'Share invite'}</button></div></section><nav class="tabs" aria-label="Community settings"><button class:active={tab==='general'} onclick={()=>selectTab('general')}>General</button><button class:active={tab==='members'} onclick={()=>selectTab('members')}>Members</button><button class:active={tab==='join'} onclick={()=>selectTab('join')}>Join mode</button><button class:active={tab==='integrations'} onclick={()=>selectTab('integrations')}>Integrations</button></nav><section class="card panel" aria-live="polite">{#if tab==='general'}<p class="label-caps">General</p><h2>Community details</h2><label for="name">Name</label><input id="name" class="text-input" bind:value={name}/><label class="check"><input type="checkbox" bind:checked={draws}/> Draws allowed</label><button class="btn btn-primary" disabled={saving} onclick={saveGeneral}>{saving?'Saving…':'Save settings'}</button>{:else if tab==='members'}<p class="label-caps">Members</p><h2>Pending requests</h2>{#if members.length===0}<p class="muted">No pending requests.</p>{:else}{#each members as member}<div class="list-row">{JSON.stringify(member)}<span>Pending</span>{#if community.membership === 'owner'}<button class="btn btn-primary" onclick={async () => { const parsed = member as { userId?: string }; if (parsed.userId) { const { api } = await import('$lib/api'); await api.approveMember(community.id, parsed.userId); await loadMembers(); } }}>Approve</button>{/if}</div>{/each}{/if}{:else if tab==='join'}<p class="label-caps">Join mode</p><h2>Who can join?</h2><div class="join-options"><button class:active={mode==='open'} onclick={()=>mode='open'}><strong>Open joining</strong><span>Players join immediately.</span></button><button class:active={mode==='approval'} onclick={()=>mode='approval'}><strong>Approval required</strong><span>Players wait for owner approval.</span></button></div><button class="btn btn-primary" disabled={saving} onclick={saveGeneral}>{saving?'Saving…':'Save join mode'}</button>{:else}<p class="label-caps">Integrations</p><h2>Preview connections</h2><label for="discord">Discord URL</label><input id="discord" class="text-input" bind:value={discord}/><label for="webhook">Webhook URL</label><input id="webhook" class="text-input" bind:value={webhook}/><button class="btn btn-primary" disabled={saving} onclick={saveIntegration}>{saving?'Saving…':'Save integrations'}</button>{/if}{#if message}<p class="status" role="status">{message}</p>{/if}</section></div></div>
<style>
.page-inner{display:flex;flex-direction:column;gap:18px;max-width:980px}.nav{display:flex}.hero,.panel{padding:28px}.hero{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;flex-wrap:wrap}.hero h1{font-size:clamp(30px,5vw,48px);line-height:1.05;margin-bottom:10px}.hero p{color:var(--theme-text-muted)}.label-caps{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--theme-accent);margin-bottom:8px}.tabs{display:flex;gap:8px;flex-wrap:wrap}.tabs button,.join-options button{padding:10px 14px;border:1px solid var(--theme-border);border-radius:999px;background:rgba(255,255,255,.04);color:var(--theme-text-muted);cursor:pointer}.tabs button.active,.join-options button.active{border-color:var(--theme-accent);background:rgba(240,90,26,.14);color:#ffd9c9}.panel h2{font-size:24px;margin-bottom:18px}.panel label{display:block;margin:12px 0 8px;font-size:13px;font-weight:700}.text-input{width:100%;margin-bottom:12px}.check{display:flex!important;gap:8px;align-items:center}.check input{accent-color:var(--theme-accent)}.join-options{display:grid;gap:10px;margin-bottom:18px}.join-options button{display:flex;flex-direction:column;align-items:flex-start;gap:5px;text-align:left;border-radius:14px}.join-options span{font-size:12px;color:var(--theme-text-muted)}.list-row{padding:12px;border-bottom:1px solid var(--theme-border);display:flex;justify-content:space-between}.status{margin-top:16px;padding:10px;border-radius:10px;background:var(--ok-bg);color:var(--ok)}
</style>
        